  calendar:()=>{if(state.calendarView==='gantt')return calendarToolbar()+ganttView();const d=state.date,y=d.getFullYear(),m=d.getMonth(),count=new Date(y,m+1,0).getDate(),offset=(new Date(y,m,1).getDay()+6)%7;const dayKey=e=>new Intl.DateTimeFormat('en-CA',{timeZone:'America/Chicago',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(e.starts_at));const monthKey=y+'-'+String(m+1).padStart(2,'0');const all=visible().filter(e=>['stage','event'].includes(e.kind)&&e.starts_at&&!isNaN(new Date(e.starts_at))).sort((a,b)=>new Date(a.starts_at)-new Date(b.starts_at));const lastKey=e=>e.ends_at?dayKey({starts_at:e.ends_at}):dayKey(e);const fromKey=monthKey+'-'+(state.day?String(state.day).padStart(2,'0'):'01'),toKey=monthKey+'-'+String(state.day||count).padStart(2,'0');const list=all.filter(e=>dayKey(e)<=toKey&&lastKey(e)>=fromKey);return `${calendarToolbar()}<div class="up-two"><section class="up-card"><div class="up-row"><button class="up-secondary" data-up-month="-1" aria-label="${t('Mes anterior','Previous month')}">‹</button><h2>${new Intl.DateTimeFormat(es()?'es-MX':'en-US',{month:'long',year:'numeric'}).format(d)}</h2><button class="up-secondary" data-up-month="1" aria-label="${t('Mes siguiente','Next month')}">›</button></div><div class="up-calendar">${(es()?['L','M','M','J','V','S','D']:['M','T','W','T','F','S','S']).map(a=>`<span>${a}</span>`).join('')}${Array.from({length:offset},()=>'<span></span>').join('')}${Array.from({length:count},(_,i)=>{const cellKey=monthKey+'-'+String(i+1).padStart(2,'0');const has=all.some(e=>dayKey(e)<=cellKey&&lastKey(e)>=cellKey);return `<button type="button" data-up-day="${i+1}" aria-label="${i+1}${has?' · '+t('Con evento','Has event'):''}" aria-pressed="${state.day===i+1}">${i+1}${has?'<i></i>':''}</button>`;}).join('')}</div><div class="up-row"><small>${t('Zona horaria: Houston · America/Chicago','Time zone: Houston · America/Chicago')}</small><button class="up-text-button" data-up-all-days>${t('Ver mes completo','View full month')}</button></div></section><section><h2>${t('Agenda','Agenda')}${state.day?' · '+state.day:''}</h2>${list.map(e=>`<article class="up-card up-event"><p class="eyebrow">${t(...kinds[e.kind])} · ${dates(e.starts_at,true)}${e.ends_at?' — '+dates(e.ends_at,true):''}</p><h2>${h(e.title)}</h2><p>${h(e.description)}</p><p class="up-muted">${h(e.data?.location||'')}</p><div class="up-card-actions"><button class="up-text-button" data-up-ics="${h(e.id)}">${t('Agregar a mi calendario','Add to my calendar')} ↗</button>${edit(e)}</div></article>`).join('')||empty(t('Sin eventos programados','No events scheduled'))}</section></div>`;},
